mapper.select:
SELECT *
FROM notes
WHERE delete_flg = 0
  AND user_id = #{user_id}
ORDER BY created_at DESC;

SELECT COUNT(*)
FROM notes
WHERE delete_flg = 0 AND user_id = #{user_id};

mapper.update:
UPDATE notes
SET delete_flg = 1
WHERE id = #{id} AND user_id = #{user_id};

mapper.select:
SELECT note_todo_items.*
FROM note_todo_items
INNER JOIN notes ON notes.id = note_todo_items.note_id
WHERE notes.user_id = #{user_id}
  AND notes.delete_flg = 0
ORDER BY note_todo_items.note_id ASC, note_todo_items.sort_order ASC;

mapper.update:
UPDATE note_todo_items
SET checked = #{checked}
WHERE id = #{id}
  AND note_id IN (SELECT id FROM notes WHERE user_id = #{user_id});

mapper.insert:
INSERT INTO note_plan_links (note_id, plan_id)
SELECT #{note_id}, #{plan_id}
WHERE EXISTS (SELECT 1 FROM notes WHERE id = #{note_id} AND user_id = #{user_id})
ON CONFLICT (note_id, plan_id) DO NOTHING;

mapper.delete:
DELETE FROM note_plan_links
WHERE note_id = #{note_id} AND plan_id = #{plan_id}
  AND note_id IN (SELECT id FROM notes WHERE user_id = #{user_id});

mapper.select:
SELECT note_attachments.*
FROM note_attachments
INNER JOIN notes ON notes.id = note_attachments.note_id
WHERE notes.user_id = #{user_id}
  AND notes.delete_flg = 0
ORDER BY note_attachments.note_id ASC, note_attachments.sort_order ASC;

mapper.insert:
INSERT INTO note_attachments (note_id, kind, github_path, commit_sha, repo_name, sort_order, provider)
SELECT #{attachment.note_id}, #{attachment.kind}, #{attachment.github_path}, #{attachment.commit_sha}, #{attachment.repo_name}, #{attachment.sort_order}, #{attachment.provider}
WHERE EXISTS (SELECT 1 FROM notes WHERE id = #{attachment.note_id} AND user_id = #{user_id});

mapper.delete:
DELETE FROM note_attachments
WHERE id = #{id}
  AND note_id IN (SELECT id FROM notes WHERE user_id = #{user_id});
